def analyze(gi,go):
    H,W=len(gi),len(gi[0])
    # label 3-components
    cid={}
    lab=-1
    for i in range(H):
        for j in range(W):
            if gi[i][j]==3 and (i,j) not in cid:
                lab+=1; q=collections.deque([(i,j)]); cid[(i,j)]=lab
                while q:
                    p,q_=q.popleft()
                    for a,b in DIRS8:
                        aa,bb=p+a,q_+b
                        if 0<=aa<H and 0<=bb<W and gi[aa][bb]==3 and (aa,bb) not in cid:
