    sizes=collections.defaultdict(int)
    for v in cid.values(): sizes[v]+=1
    iso=[]
    for i in range(H):
        for j in range(W):
            if gi[i][j]==2 and not any(0<=i+a<H and 0<=j+b<W and gi[i+a][j+b]==2 for a,b in DIRS8):
                iso.append((i,j))
    # per 3-cell: features
    feats=[]
    for i in range(H):
        for j in range(W):
            if gi[i][j]!=3: continue
            conv = go[i][j]==1
            adjiso=[]
            for a,b in DIRS8:
                ii,jj=i+a,j+b
                if 0<=ii<H and 0<=jj<W and gi[ii][jj]==2:
                    if not any(0<=ii+x<H and 0<=jj+y<W and gi[ii+x][jj+y]==2 for x,y in DIRS8):
                        adjiso.append((ii,jj))
            niso=len(adjiso)
            feats.append((i,j,sizes[cid[(i,j)]],conv,niso,tuple(sorted((a,b) for a,b in adjiso))) if True else None)
    return feats,iso,sizes

